import { useState, useMemo } from 'react';
import { Download, FileText, User, Snowflake, History } from 'lucide-react';
import { ColumnDef } from '@tanstack/react-table';
import DataTable from '@/components/common/DataTable';
import Badge from '@/components/common/Badge';
import Modal from '@/components/common/Modal';
import { PrimaryButton, DefaultButton, TextButton } from '@/components/common/Button';
import { SearchBar, SearchField } from '@/components/common/SearchField';
import { useStore } from '@/store/useStore';
import * as XLSX from 'xlsx';
import FeatureHelpButton from '@/components/common/FeatureHelpButton';

interface WorkOrderSummary {
  workOrderId: string;
  workOrderCode: string;
  workOrderName: string;
  projectId: string;
  projectName: string;
  outboundCount: number;
  outboundQuantity: number;
  returnCount: number;
  returnQuantity: number;
  productCount: number;
  outboundOrders: any[];
  returnOrders: any[];
  isFrozen: boolean;
}

const helpContent = {
  title: '展会物资领用报表 - 功能操作说明',
  description: '按项目/时间等条件统计展会物资领用数据；支持导出报表和项目冻结管理',
  sections: [
    {
      heading: '数据筛选',
      items: [
        '可按项目筛选特定项目的领用数据',
        '可按日期范围筛选出库单日期内的数据',
      ]
    },
    {
      heading: '报表数据说明',
      items: [
        '以项目为维度汇总统计物资领用情况',
        '领用总数量：展会出库单出库数量汇总',
        '归还总数量：退库单归还数量汇总',
        '差异 = 领用总数量 - 归还总数量',
        '已冻结项目在项目名称旁显示"已冻结"标签',
      ]
    },
    {
      heading: '冻结功能说明',
      items: [
        '点击"冻结展会物料领用"按钮可批量冻结项目',
        '冻结操作会限制项目关联的业务操作',
        '已冻结项目的出库单无法编辑、删除或确认出库',
        '已冻结项目的出库单无法发起归还入库',
        '已冻结项目的归还入库单无法提交或确认入库',
        '点击列表中的"冻结"按钮可单独冻结某个项目',
        '点击"解冻项目"按钮可解冻已冻结的项目',
        '点击"操作日志"按钮可查看所有冻结/解冻操作记录',
      ]
    },
    {
      heading: '其他操作',
      items: [
        '点击项目名称或"详情"按钮查看项目关联订单明细',
        '点击"导出Excel"按钮导出当前筛选结果',
      ]
    }
  ]
};
export default function ExhibitionRequisitionReport() {
  const { outboundOrders, returnOrders, products, workOrderConfigs, frozenProjects, freezeLogs, freezeProjects, unfreezeProjects, currentUser } = useStore();
  const [filterWorkOrder, setFilterWorkOrder] = useState('');
  const [filterStartDate, setFilterStartDate] = useState('');
  const [filterEndDate, setFilterEndDate] = useState('');
  const [appliedFilter, setAppliedFilter] = useState({
    workOrder: '',
    startDate: '',
    endDate: '',
  });
  const [selectedWorkOrder, setSelectedWorkOrder] = useState<WorkOrderSummary | null>(null);
  const [freezeModalOpen, setFreezeModalOpen] = useState(false);
  const [unfreezeModalOpen, setUnfreezeModalOpen] = useState(false);
  const [logModalOpen, setLogModalOpen] = useState(false);
  const [selectedProjectIds, setSelectedProjectIds] = useState<string[]>([]);
  const [freezeRemark, setFreezeRemark] = useState('');
  const [unfreezeRemark, setUnfreezeRemark] = useState('');
  const [freezeSearchKeyword, setFreezeSearchKeyword] = useState('');
  const [unfreezeSearchKeyword, setUnfreezeSearchKeyword] = useState('');

  const reportData = useMemo(() => {
    const exhibitionOutboundOrders = outboundOrders.filter(
      o => o.type === 'exhibition' && o.status === 'submitted'
    );

    const submittedReturnOrders = returnOrders.filter(
      r => r.type === 'return' && r.status === 'submitted'
    );

    const projectMap = new Map<string, WorkOrderSummary>();

    exhibitionOutboundOrders.forEach(order => {
      const orderDate = order.createTime?.slice(0, 10) || '';

      if (appliedFilter.startDate && orderDate < appliedFilter.startDate) return;
      if (appliedFilter.endDate && orderDate > appliedFilter.endDate) return;

      const orderProjects = new Map<string, { projectId: string; projectName: string; workOrderId: string; workOrderCode: string; workOrderName: string; quantity: number }>();

      order.details.forEach((detail: any) => {
        if (detail.workOrderId) {
          const config = workOrderConfigs.find(c => c.workOrderId === detail.workOrderId);
          const projectId = config?.projectId || '';
          const projectName = config?.projectName || '';
          
          const existing = orderProjects.get(projectId);
          if (existing) {
            existing.quantity += detail.quantity || 0;
          } else {
            orderProjects.set(projectId, {
              projectId,
              projectName,
              workOrderId: detail.workOrderId,
              workOrderCode: detail.workOrderCode || '',
              workOrderName: detail.workOrderName || '',
              quantity: detail.quantity || 0,
            });
          }
        }
      });

      orderProjects.forEach(p => {
        const existing = projectMap.get(p.projectId);
        if (existing) {
          existing.outboundCount += 1;
          existing.outboundQuantity += p.quantity;
          existing.outboundOrders.push(order);
        } else {
          projectMap.set(p.projectId, {
            workOrderId: p.workOrderId,
            workOrderCode: p.workOrderCode,
            workOrderName: p.workOrderName,
            projectId: p.projectId,
            projectName: p.projectName,
            outboundCount: 1,
            outboundQuantity: p.quantity,
            returnCount: 0,
            returnQuantity: 0,
            productCount: 0,
            outboundOrders: [order],
            returnOrders: [],
            isFrozen: false,
          });
        }
      });
    });

    submittedReturnOrders.forEach(returnOrder => {
      const sourceOrder = exhibitionOutboundOrders.find(o => o.id === returnOrder.sourceOrderId);
      if (!sourceOrder) return;

      const returnDate = returnOrder.createTime?.slice(0, 10) || '';
      if (appliedFilter.startDate && returnDate < appliedFilter.startDate) return;
      if (appliedFilter.endDate && returnDate > appliedFilter.endDate) return;

      const returnProjects = new Map<string, { projectId: string; projectName: string; workOrderId: string; workOrderCode: string; workOrderName: string; quantity: number }>();

      returnOrder.details.forEach((detail: any) => {
        if (detail.workOrderId) {
          const config = workOrderConfigs.find(c => c.workOrderId === detail.workOrderId);
          const projectId = config?.projectId || '';
          const projectName = config?.projectName || '';
          
          const existing = returnProjects.get(projectId);
          if (existing) {
            existing.quantity += detail.quantity || 0;
          } else {
            returnProjects.set(projectId, {
              projectId,
              projectName,
              workOrderId: detail.workOrderId,
              workOrderCode: detail.workOrderCode || '',
              workOrderName: detail.workOrderName || '',
              quantity: detail.quantity || 0,
            });
          }
        }
      });

      returnProjects.forEach(p => {
        const existing = projectMap.get(p.projectId);
        if (existing) {
          existing.returnCount += 1;
          existing.returnQuantity += p.quantity;
          existing.returnOrders.push(returnOrder);
        } else {
          projectMap.set(p.projectId, {
            workOrderId: p.workOrderId,
            workOrderCode: p.workOrderCode,
            workOrderName: p.workOrderName,
            projectId: p.projectId,
            projectName: p.projectName,
            outboundCount: 0,
            outboundQuantity: 0,
            returnCount: 1,
            returnQuantity: p.quantity,
            productCount: 0,
            outboundOrders: [],
            returnOrders: [returnOrder],
            isFrozen: false,
          });
        }
      });
    });

    projectMap.forEach(summary => {
      const productSet = new Set<string>();
      summary.outboundOrders.forEach(order => {
        order.details.forEach((d: any) => {
          if (d.productId) {
            const config = workOrderConfigs.find(c => c.workOrderId === d.workOrderId);
            if (config?.projectId === summary.projectId) {
              productSet.add(d.productId);
            }
          }
        });
      });
      summary.returnOrders.forEach(order => {
        order.details.forEach((d: any) => {
          if (d.productId) {
            const config = workOrderConfigs.find(c => c.workOrderId === d.workOrderId);
            if (config?.projectId === summary.projectId) {
              productSet.add(d.productId);
            }
          }
        });
      });
      summary.productCount = productSet.size;
      summary.isFrozen = frozenProjects.some(f => f.projectId === summary.projectId);
    });

    let result = Array.from(projectMap.values());

    if (appliedFilter.workOrder) {
      result = result.filter(item => item.projectId === appliedFilter.workOrder);
    }

    return result;
  }, [outboundOrders, returnOrders, appliedFilter, workOrderConfigs, frozenProjects]);
  const totalWorkOrders = reportData.length;
  const totalOutbound = reportData.reduce((sum, d) => sum + d.outboundQuantity, 0);
  const totalReturn = reportData.reduce((sum, d) => sum + d.returnQuantity, 0);
  const totalDiff = totalOutbound - totalReturn;

  const columns: ColumnDef<WorkOrderSummary, unknown>[] = [
    {
      accessorKey: 'projectId',
      header: '项目编号',
      cell: ({ row }) => row.original.projectId || '-',
    },
    {
      accessorKey: 'projectName',
      header: '项目名称',
      cell: ({ row }) => (
        <div className="flex items-center gap-2">
          <TextButton
            onClick={() => setSelectedWorkOrder(row.original)}
            className="!p-0 !h-auto"
          >
            {row.original.projectName || '-'}
          </TextButton>
          {row.original.isFrozen && (
            <Badge variant="warning" className="text-xs">
              已冻结
            </Badge>
          )}
        </div>
      ),
    },
    {
      accessorKey: 'outboundCount',
      header: '领用单数',
      cell: ({ row }) => (
        <span className="font-medium">{row.original.outboundCount}</span>
      ),
    },
    {
      accessorKey: 'outboundQuantity',
      header: '领用总数量',
      cell: ({ row }) => (
        <span className="text-blue-600 font-medium">{row.original.outboundQuantity}</span>
      ),
    },
    {
      accessorKey: 'returnCount',
      header: '归还单数',
      cell: ({ row }) => row.original.returnCount,
    },
    {
      accessorKey: 'returnQuantity',
      header: '归还总数量',
      cell: ({ row }) => (
        <span className="text-green-600 font-medium">{row.original.returnQuantity}</span>
      ),
    },
    {
      accessorKey: 'productCount',
      header: '物料种类',
      cell: ({ row }) => row.original.productCount,
    },
    {
      id: 'diff',
      header: '差异(领用-归还)',
      cell: ({ row }) => {
        const diff = row.original.outboundQuantity - row.original.returnQuantity;
        return (
          <span className={diff > 0 ? 'text-orange-600' : diff < 0 ? 'text-red-600' : 'text-slate-500'}>
            {diff > 0 ? '+' : ''}{diff}
          </span>
        );
      },
    },
    {
      id: 'actions',
      header: '操作',
      cell: ({ row }) => (
        <div className="flex items-center gap-2">
          <TextButton
            onClick={() => setSelectedWorkOrder(row.original)}
          >
            详情
          </TextButton>
          {row.original.isFrozen ? (
            <TextButton
              type="warning"
              onClick={() => {
                setSelectedProjectIds([row.original.projectId]);
                setUnfreezeRemark('');
                setUnfreezeModalOpen(true);
              }}
            >
              解冻
            </TextButton>
          ) : (
            <TextButton
              onClick={() => {
                setSelectedProjectIds([row.original.projectId]);
                setFreezeRemark('');
                setFreezeModalOpen(true);
              }}
            >
              冻结
            </TextButton>
          )}
        </div>
      ),
    },
  ];
  const workOrderOptions = useMemo(() => {
    const map = new Map<string, { value: string; label: string }>();
    outboundOrders
      .filter(o => o.type === 'exhibition' && o.status === 'submitted')
      .forEach(order => {
        order.details.forEach((d: any) => {
          if (d.workOrderId && !map.has(d.workOrderId)) {
            const config = workOrderConfigs.find(c => c.workOrderId === d.workOrderId);
            if (config && config.projectId && !map.has(config.projectId)) {
              map.set(config.projectId, {
                value: config.projectId,
                label: config.projectName || config.projectId,
              });
            }
          }
        });
      });
    return Array.from(map.values());
  }, [outboundOrders, workOrderConfigs]);

  const handleExport = () => {
    if (reportData.length === 0) {
      alert('没有可导出的数据');
      return;
    }

    const exportData = reportData.map(item => ({
      '项目编号': item.projectId || '-',
      '项目名称': item.projectName || '-',
      '领用单数': item.outboundCount,
      '领用总数量': item.outboundQuantity,
      '归还单数': item.returnCount,
      '归还总数量': item.returnQuantity,
      '物料种类': item.productCount,
      '差异(领用-归还)': item.outboundQuantity - item.returnQuantity,
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, '展会物资领用报表');
    XLSX.writeFile(wb, `展会物资领用报表_${new Date().toISOString().slice(0, 10)}.xlsx`);
  };

  const allProjects = useMemo(() => {
    const map = new Map<string, { projectId: string; projectName: string; isFrozen: boolean }>();
    reportData.forEach(item => {
      if (item.projectId && !map.has(item.projectId)) {
        map.set(item.projectId, {
          projectId: item.projectId,
          projectName: item.projectName || item.projectId,
          isFrozen: item.isFrozen,
        });
      }
    });
    return Array.from(map.values());
  }, [reportData]);

  const unfreezableProjects = useMemo(() => {
    return allProjects.filter(p => p.isFrozen);
  }, [allProjects]);

  const freezableProjects = useMemo(() => {
    return allProjects.filter(p => !p.isFrozen);
  }, [allProjects]);

  const filteredFreezeProjects = useMemo(() => {
    if (!freezeSearchKeyword) return freezableProjects;
    const keyword = freezeSearchKeyword.toLowerCase();
    return freezableProjects.filter(p =>
      p.projectName.toLowerCase().includes(keyword) ||
      p.projectId.toLowerCase().includes(keyword)
    );
  }, [freezableProjects, freezeSearchKeyword]);

  const filteredUnfreezeProjects = useMemo(() => {
    if (!unfreezeSearchKeyword) return unfreezableProjects;
    const keyword = unfreezeSearchKeyword.toLowerCase();
    return unfreezableProjects.filter(p =>
      p.projectName.toLowerCase().includes(keyword) ||
      p.projectId.toLowerCase().includes(keyword)
    );
  }, [unfreezableProjects, unfreezeSearchKeyword]);

  const handleOpenFreezeModal = () => {
    setSelectedProjectIds([]);
    setFreezeRemark('');
    setFreezeSearchKeyword('');
    setFreezeModalOpen(true);
  };

  const handleOpenUnfreezeModal = () => {
    setSelectedProjectIds([]);
    setUnfreezeRemark('');
    setUnfreezeSearchKeyword('');
    setUnfreezeModalOpen(true);
  };

  const handleConfirmFreeze = () => {
    if (selectedProjectIds.length === 0) {
      alert('请选择要冻结的项目');
      return;
    }
    const projects = allProjects
      .filter(p => selectedProjectIds.includes(p.projectId))
      .map(p => ({ projectId: p.projectId, projectName: p.projectName }));
    freezeProjects(projects, currentUser.name, freezeRemark || undefined);
    setFreezeModalOpen(false);
    setSelectedProjectIds([]);
  };

  const handleConfirmUnfreeze = () => {
    if (selectedProjectIds.length === 0) {
      alert('请选择要解冻的项目');
      return;
    }
    unfreezeProjects(selectedProjectIds, currentUser.name, unfreezeRemark || undefined);
    setUnfreezeModalOpen(false);
    setSelectedProjectIds([]);
  };

  const toggleProjectSelection = (projectId: string) => {
    setSelectedProjectIds(prev =>
      prev.includes(projectId)
        ? prev.filter(id => id !== projectId)
        : [...prev, projectId]
    );
  };

  const toggleSelectAll = (projects: { projectId: string }[]) => {
    if (selectedProjectIds.length === projects.length) {
      setSelectedProjectIds([]);
    } else {
      setSelectedProjectIds(projects.map(p => p.projectId));
    }
  };

  const workOrderDetailData = useMemo(() => {
    if (!selectedWorkOrder) return null;

    const outboundDetails = selectedWorkOrder.outboundOrders.map(order => {
      const woDetails = order.details.filter((d: any) => {
        const config = workOrderConfigs.find(c => c.workOrderId === d.workOrderId);
        return config?.projectId === selectedWorkOrder.projectId;
      });
      return {
        orderNo: order.orderNo,
        type: 'exhibition',
        typeLabel: '展会出库单',
        operator: order.operator,
        createTime: order.createTime,
        totalQuantity: woDetails.reduce((s: number, d: any) => s + (d.quantity || 0), 0),
        details: woDetails.map((d: any) => {
          const product = products.find(p => p.id === d.productId);
          return {
            ...d,
            productName: product?.name || d.productName || '-',
            productCode: product?.code || d.productCode || '-',
            categoryName: product?.categoryName || '',
            unit: product?.unit || '',
          };
        }),
      };
    });

    const returnDetails = selectedWorkOrder.returnOrders.map(order => {
      const woDetails = order.details.filter((d: any) => {
        const config = workOrderConfigs.find(c => c.workOrderId === d.workOrderId);
        return config?.projectId === selectedWorkOrder.projectId;
      });
      return {
        orderNo: order.orderNo,
        type: 'return',
        typeLabel: '退库单',
        operator: order.operator,
        createTime: order.createTime,
        totalQuantity: woDetails.reduce((s: number, d: any) => s + (d.quantity || 0), 0),
        details: woDetails.map((d: any) => {
          const product = products.find(p => p.id === d.productId);
          return {
            ...d,
            productName: product?.name || d.productName || '-',
            productCode: product?.code || d.productCode || '-',
            categoryName: product?.categoryName || '',
            unit: product?.unit || '',
          };
        }),
      };
    });

    return { workOrder: selectedWorkOrder, outboundOrders: outboundDetails, returnOrders: returnDetails };
  }, [selectedWorkOrder, products, workOrderConfigs]);
  return (
    <div className="p-4">
      <div className="mb-3 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <h2 className="text-sm font-semibold text-[#303133]">展会物资领用报表</h2>
          <FeatureHelpButton content={helpContent} />
        </div>
        <div className="flex items-center gap-2">
          <PrimaryButton onClick={handleOpenFreezeModal}>
            <Snowflake size={16} />
            冻结展会物料领用
          </PrimaryButton>
          <DefaultButton onClick={handleOpenUnfreezeModal}>
            解冻项目
          </DefaultButton>
          <DefaultButton onClick={() => setLogModalOpen(true)}>
            <History size={16} />
            操作日志
          </DefaultButton>
          <DefaultButton onClick={handleExport}>
            <Download size={16} />
            导出
          </DefaultButton>
        </div>
      </div>

      <SearchBar
        onSearch={() =>
          setAppliedFilter({
            workOrder: filterWorkOrder,
            startDate: filterStartDate,
            endDate: filterEndDate,
          })
        }
        onReset={() => {
          setFilterWorkOrder('');
          setFilterStartDate('');
          setFilterEndDate('');
          setAppliedFilter({
            workOrder: '',
            startDate: '',
            endDate: '',
          });
        }}
      >
        <SearchField
          label="项目"
          type="select"
          options={workOrderOptions}
          value={filterWorkOrder}
          onChange={setFilterWorkOrder}
          placeholder="全部项目"
        />
        <SearchField
          label="开始日期"
          type="date"
          value={filterStartDate}
          onChange={setFilterStartDate}
        />
        <SearchField
          label="结束日期"
          type="date"
          value={filterEndDate}
          onChange={setFilterEndDate}
        />
      </SearchBar>

      <div className="grid grid-cols-4 gap-4 mb-4">
        <div className="bg-slate-50 rounded-lg p-4">
          <p className="text-sm text-slate-500">项目数</p>
          <p className="text-2xl font-bold text-slate-900">{totalWorkOrders}</p>
        </div>
        <div className="bg-slate-50 rounded-lg p-4">
          <p className="text-sm text-slate-500">领用总数量</p>
          <p className="text-2xl font-bold text-blue-600">{totalOutbound}</p>
        </div>
        <div className="bg-slate-50 rounded-lg p-4">
          <p className="text-sm text-slate-500">归还总数量</p>
          <p className="text-2xl font-bold text-green-600">{totalReturn}</p>
        </div>
        <div className="bg-slate-50 rounded-lg p-4">
          <p className="text-sm text-slate-500">差异(领用-归还)</p>
          <p className="text-2xl font-bold text-orange-600">{totalDiff}</p>
        </div>
      </div>

      <div className="bg-white rounded shadow-sm border border-[#e4e7ed]">
        <DataTable data={reportData} columns={columns} pageSize={15} />
      </div>
      <Modal
        open={!!selectedWorkOrder}
        onClose={() => setSelectedWorkOrder(null)}
        title="项目详情"
        size="max-w-4xl"
      >
        {workOrderDetailData && (
          <div className="space-y-4">
            <div className="border border-slate-200 rounded-lg p-4 bg-slate-50">
              <h3 className="text-sm font-semibold text-slate-700 mb-3">项目基本信息</h3>
              <div className="grid grid-cols-2 gap-3 text-sm">
                <div className="flex items-center gap-2">
                  <FileText size={14} className="text-slate-400" />
                  <span className="text-slate-500">项目编号：</span>
                  <span className="font-medium">{workOrderDetailData.workOrder.projectId || '-'}</span>
                </div>
                <div className="flex items-center gap-2">
                  <FileText size={14} className="text-slate-400" />
                  <span className="text-slate-500">项目名称：</span>
                  <span className="font-medium">{workOrderDetailData.workOrder.projectName || '-'}</span>
                </div>
                <div className="flex items-center gap-2">
                  <User size={14} className="text-slate-400" />
                  <span className="text-slate-500">领用单数：</span>
                  <span>{workOrderDetailData.workOrder.outboundCount}</span>
                </div>
                <div className="flex items-center gap-2">
                  <User size={14} className="text-slate-400" />
                  <span className="text-slate-500">归还单数：</span>
                  <span>{workOrderDetailData.workOrder.returnCount}</span>
                </div>
              </div>
            </div>
            <div>
              <h3 className="text-sm font-semibold text-slate-700 mb-3">
                领用订单（{workOrderDetailData.outboundOrders.length}）
              </h3>
              {workOrderDetailData.outboundOrders.length === 0 ? (
                <div className="text-center py-8 text-slate-400 border border-slate-200 rounded-lg">
                  暂无领用订单
                </div>
              ) : (
                <div className="space-y-3 max-h-[300px] overflow-y-auto">
                  {workOrderDetailData.outboundOrders.map((order, idx) => (
                    <div key={`out-${idx}`} className="border border-slate-200 rounded-lg overflow-hidden">
                      <div className="bg-slate-50 px-4 py-2 flex items-center justify-between text-sm">
                        <div className="flex items-center gap-3">
                          <span className="font-medium">{order.orderNo}</span>
                          <Badge variant="default">
                            {order.typeLabel}
                          </Badge>
                        </div>
                        <div className="text-xs text-slate-500">
                          {order.createTime} | {order.operator}
                        </div>
                      </div>
                      <table className="w-full text-xs">
                        <thead className="bg-slate-50">
                          <tr>
                            <th className="px-3 py-2 text-left font-medium text-slate-600">物料编码</th>
                            <th className="px-3 py-2 text-left font-medium text-slate-600">物料名称</th>
                            <th className="px-3 py-2 text-left font-medium text-slate-600">规格</th>
                            <th className="px-3 py-2 text-left font-medium text-slate-600">单位</th>
                            <th className="px-3 py-2 text-right font-medium text-slate-600">数量</th>
                          </tr>
                        </thead>
                        <tbody>
                          {order.details.map((d: any, i: number) => (
                            <tr key={i} className="border-t border-slate-100">
                              <td className="px-3 py-2">{d.productCode}</td>
                              <td className="px-3 py-2">{d.productName}</td>
                              <td className="px-3 py-2">{d.specification || '-'}</td>
                              <td className="px-3 py-2">{d.unit || '-'}</td>
                              <td className="px-3 py-2 text-right font-medium">{d.quantity}</td>
                            </tr>
                          ))}
                          <tr className="bg-slate-50 border-t border-slate-200">
                            <td colSpan={4} className="px-3 py-2 text-right font-medium text-slate-600">合计</td>
                            <td className="px-3 py-2 text-right font-bold text-blue-600">{order.totalQuantity}</td>
                          </tr>
                        </tbody>
                      </table>
                    </div>
                  ))}
                </div>
              )}
            </div>
            <div>
              <h3 className="text-sm font-semibold text-slate-700 mb-3">
                归还订单（{workOrderDetailData.returnOrders.length}）
              </h3>
              {workOrderDetailData.returnOrders.length === 0 ? (
                <div className="text-center py-8 text-slate-400 border border-slate-200 rounded-lg">
                  暂无归还订单
                </div>
              ) : (
                <div className="space-y-3 max-h-[300px] overflow-y-auto">
                  {workOrderDetailData.returnOrders.map((order, idx) => (
                    <div key={`ret-${idx}`} className="border border-slate-200 rounded-lg overflow-hidden">
                      <div className="bg-slate-50 px-4 py-2 flex items-center justify-between text-sm">
                        <div className="flex items-center gap-3">
                          <span className="font-medium">{order.orderNo}</span>
                          <Badge variant="success">
                            {order.typeLabel}
                          </Badge>
                        </div>
                        <div className="text-xs text-slate-500">
                          {order.createTime} | {order.operator}
                        </div>
                      </div>
                      <table className="w-full text-xs">
                        <thead className="bg-slate-50">
                          <tr>
                            <th className="px-3 py-2 text-left font-medium text-slate-600">物料编码</th>
                            <th className="px-3 py-2 text-left font-medium text-slate-600">物料名称</th>
                            <th className="px-3 py-2 text-left font-medium text-slate-600">规格</th>
                            <th className="px-3 py-2 text-left font-medium text-slate-600">单位</th>
                            <th className="px-3 py-2 text-right font-medium text-slate-600">数量</th>
                          </tr>
                        </thead>
                        <tbody>
                          {order.details.map((d: any, i: number) => (
                            <tr key={i} className="border-t border-slate-100">
                              <td className="px-3 py-2">{d.productCode}</td>
                              <td className="px-3 py-2">{d.productName}</td>
                              <td className="px-3 py-2">{d.specification || '-'}</td>
                              <td className="px-3 py-2">{d.unit || '-'}</td>
                              <td className="px-3 py-2 text-right font-medium">{d.quantity}</td>
                            </tr>
                          ))}
                          <tr className="bg-slate-50 border-t border-slate-200">
                            <td colSpan={4} className="px-3 py-2 text-right font-medium text-slate-600">合计</td>
                            <td className="px-3 py-2 text-right font-bold text-green-600">{order.totalQuantity}</td>
                          </tr>
                        </tbody>
                      </table>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t">
              <DefaultButton onClick={() => setSelectedWorkOrder(null)}>
                关闭
              </DefaultButton>
            </div>
          </div>
        )}
      </Modal>

      <Modal
        open={freezeModalOpen}
        onClose={() => setFreezeModalOpen(false)}
        title="冻结展会物料领用"
        size="max-w-lg"
      >
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">
              选择要冻结的项目（可多选）
            </label>
            <input
              type="text"
              placeholder="搜索项目名称或编号"
              value={freezeSearchKeyword}
              onChange={(e) => setFreezeSearchKeyword(e.target.value)}
              className="w-full mb-3 h-9 px-3 border border-slate-200 text-sm text-slate-700 placeholder:text-slate-400 rounded-lg focus:outline-none focus:border-indigo-500 focus:shadow-sm focus:shadow-indigo-200 transition-all duration-200 bg-white"
            />
            <div className="border border-slate-200 rounded-lg max-h-80 overflow-y-auto">
              <div className="sticky top-0 bg-slate-50 px-3 py-2 border-b border-slate-200 flex items-center gap-2">
                <input
                  type="checkbox"
                  checked={filteredFreezeProjects.length > 0 && selectedProjectIds.length === filteredFreezeProjects.length}
                  onChange={() => toggleSelectAll(filteredFreezeProjects)}
                  className="rounded"
                />
                <span className="text-sm font-medium text-slate-600">
                  全选（{selectedProjectIds.length}/{filteredFreezeProjects.length}）
                </span>
              </div>
              {filteredFreezeProjects.length === 0 ? (
                <div className="text-center py-8 text-slate-400">
                  暂无可冻结的项目
                </div>
              ) : (
                filteredFreezeProjects.map(project => (
                  <div
                    key={project.projectId}
                    className="px-3 py-2 border-b border-slate-100 last:border-b-0 flex items-center gap-2 hover:bg-slate-50 cursor-pointer"
                    onClick={() => toggleProjectSelection(project.projectId)}
                  >
                    <input
                      type="checkbox"
                      checked={selectedProjectIds.includes(project.projectId)}
                      onChange={() => toggleProjectSelection(project.projectId)}
                      className="rounded"
                    />
                    <div className="flex-1">
                      <div className="text-sm font-medium text-slate-800">{project.projectName}</div>
                      <div className="text-xs text-slate-500">{project.projectId}</div>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">
              冻结原因（选填）
            </label>
            <textarea
              value={freezeRemark}
              onChange={(e) => setFreezeRemark(e.target.value)}
              placeholder="请输入冻结原因..."
              className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              rows={3}
            />
          </div>
          <div className="flex justify-end gap-3 pt-2 border-t">
            <DefaultButton onClick={() => setFreezeModalOpen(false)}>
              取消
            </DefaultButton>
            <PrimaryButton onClick={handleConfirmFreeze}>
              确定冻结
            </PrimaryButton>
          </div>
        </div>
      </Modal>

      <Modal
        open={unfreezeModalOpen}
        onClose={() => setUnfreezeModalOpen(false)}
        title="解冻项目"
        size="max-w-lg"
      >
        <div className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">
              选择要解冻的项目（可多选）
            </label>
            <input
              type="text"
              placeholder="搜索项目名称或编号"
              value={unfreezeSearchKeyword}
              onChange={(e) => setUnfreezeSearchKeyword(e.target.value)}
              className="w-full mb-3 h-9 px-3 border border-slate-200 text-sm text-slate-700 placeholder:text-slate-400 rounded-lg focus:outline-none focus:border-indigo-500 focus:shadow-sm focus:shadow-indigo-200 transition-all duration-200 bg-white"
            />
            <div className="border border-slate-200 rounded-lg max-h-80 overflow-y-auto">
              <div className="sticky top-0 bg-slate-50 px-3 py-2 border-b border-slate-200 flex items-center gap-2">
                <input
                  type="checkbox"
                  checked={filteredUnfreezeProjects.length > 0 && selectedProjectIds.length === filteredUnfreezeProjects.length}
                  onChange={() => toggleSelectAll(filteredUnfreezeProjects)}
                  className="rounded"
                />
                <span className="text-sm font-medium text-slate-600">
                  全选（{selectedProjectIds.length}/{filteredUnfreezeProjects.length}）
                </span>
              </div>
              {filteredUnfreezeProjects.length === 0 ? (
                <div className="text-center py-8 text-slate-400">
                  暂无已冻结的项目
                </div>
              ) : (
                filteredUnfreezeProjects.map(project => (
                  <div
                    key={project.projectId}
                    className="px-3 py-2 border-b border-slate-100 last:border-b-0 flex items-center gap-2 hover:bg-slate-50 cursor-pointer"
                    onClick={() => toggleProjectSelection(project.projectId)}
                  >
                    <input
                      type="checkbox"
                      checked={selectedProjectIds.includes(project.projectId)}
                      onChange={() => toggleProjectSelection(project.projectId)}
                      className="rounded"
                    />
                    <div className="flex-1">
                      <div className="text-sm font-medium text-slate-800">{project.projectName}</div>
                      <div className="text-xs text-slate-500">{project.projectId}</div>
                    </div>
                    <Badge variant="warning" className="text-xs">已冻结</Badge>
                  </div>
                ))
              )}
            </div>
          </div>
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">
              解冻原因（选填）
            </label>
            <textarea
              value={unfreezeRemark}
              onChange={(e) => setUnfreezeRemark(e.target.value)}
              placeholder="请输入解冻原因..."
              className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              rows={3}
            />
          </div>
          <div className="flex justify-end gap-3 pt-2 border-t">
            <DefaultButton onClick={() => setUnfreezeModalOpen(false)}>
              取消
            </DefaultButton>
            <PrimaryButton onClick={handleConfirmUnfreeze}>
              确定解冻
            </PrimaryButton>
          </div>
        </div>
      </Modal>

      <Modal
        open={logModalOpen}
        onClose={() => setLogModalOpen(false)}
        title="冻结操作日志"
        size="max-w-3xl"
      >
        <div className="space-y-3">
          {freezeLogs.length === 0 ? (
            <div className="text-center py-8 text-slate-400">
              暂无操作日志
            </div>
          ) : (
            <div className="max-h-96 overflow-y-auto space-y-2">
              {freezeLogs.map(log => (
                <div key={log.id} className="border border-slate-200 rounded-lg p-3">
                  <div className="flex items-center justify-between mb-2">
                    <div className="flex items-center gap-2">
                      <Badge variant={log.operateType === 'freeze' ? 'warning' : 'success'} className="text-xs">
                        {log.operateType === 'freeze' ? '冻结' : '解冻'}
                      </Badge>
                      <span className="text-sm font-medium text-slate-700">
                        {log.operator}
                      </span>
                    </div>
                    <span className="text-xs text-slate-500">{log.operateTime}</span>
                  </div>
                  <div className="text-sm text-slate-600 mb-1">
                    <span className="text-slate-500">操作项目：</span>
                    {log.projectNames.join('、')}
                  </div>
                  {log.remark && (
                    <div className="text-sm text-slate-600">
                      <span className="text-slate-500">备注：</span>
                      {log.remark}
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
          <div className="flex justify-end pt-3 border-t">
            <DefaultButton onClick={() => setLogModalOpen(false)}>
              关闭
            </DefaultButton>
          </div>
        </div>
      </Modal>
    </div>
  );
}